import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
const exec=promisify(execFile);
export async function fixtureGit(secondCommit=false,documentChange=false){const folder=await fs.mkdtemp(path.join(os.tmpdir(),'contribution-git-contract-'));const work=path.join(folder,'work'),bare=path.join(folder,'repo.git');await fs.mkdir(work);await exec('git',['init','-b','main',work]);await fs.writeFile(path.join(work,'README.md'),'# Contract repository\nRequirements: preserve boundary correctness and test results.\n');await fs.writeFile(path.join(work,'code.py'),'def boundary(value):\n    return value > 0\n');await exec('git',['-C',work,'add','.']);await exec('git',['-C',work,'-c','user.name=Contract Author','-c','user.email=member-a@company.example','commit','-m','Implement explicit boundary'],{env:{...process.env,GIT_AUTHOR_DATE:'2025-01-01T01:00:00Z',GIT_COMMITTER_DATE:'2025-01-01T01:00:00Z'}});if(secondCommit){if(documentChange)await fs.appendFile(path.join(work,'README.md'),'Usage: use the explicit input boundary and regression coverage.\n');await fs.writeFile(path.join(work,'test_boundary.py'),'from code import boundary\n\ndef test_boundary():\n    assert boundary(1)\n    assert not boundary(0)\n');await exec('git',['-C',work,'add','.']);await exec('git',['-C',work,'-c','user.name=Contract Author','-c','user.email=member-a@company.example','commit','-m','Add boundary regression coverage'],{env:{...process.env,GIT_AUTHOR_DATE:'2025-01-02T01:00:00Z',GIT_COMMITTER_DATE:'2025-01-02T01:00:00Z'}});}await exec('git',['clone','--mirror',work,bare]);return {bare,cleanup:()=>fs.rm(folder,{recursive:true,force:true})};}
